Code
lasso_test_time &lt;- lasso_estimates |&gt; filter(estimate != 0 & term != "(Intercept)") |&gt;
  mutate(task = str_split_i(term, "_", 1)) |&gt;
  inner_join(v5_dat |&gt; select(item, time) |&gt; unique(),
