LASSO Tuning
Tuning the penalty argument.


Code
# tune penalty instead of fixing it
# mixture = 1 for LASSO
lasso_tune_spec &lt;- linear_reg(penalty = tune(), mixture = 1) |&gt;
  set_engine("glmnet")




Code
# set.seed(1234)
# 
# # splitting data
# v5_dat_split &lt;- initial_split(v5_dat_wide)
# 
# v5_dat_train &lt;- training(v5_dat_split)
# v5_dat_test &lt;- testing(v5_dat_split)




lambda_grid &lt;- grid_regular(penalty(), levels = 50)

doParallel::registerDoParallel()

lasso_grid &lt;- tune_grid(
  wf |&gt; add_model(lasso_tune_spec),
  resamples = v5_dat_boot,
  grid = lambda_grid,
  metrics = metric_set(rmse)
)

saveRDS(lasso_grid, here::here("Data", "lasso-estimates_tuning.rds"))




Code
lasso_grid &lt;- readRDS(here::here("Data", "lasso-estimates_tuning.rds"))

lowest_rmse &lt;- lasso_grid |&gt;
  select_best(metric = "rmse")

final_lasso &lt;- finalize_workflow(
  wf |&gt; add_model(lasso_tune_spec),
  lowest_rmse
)

saveRDS(final_lasso, here::here("Data", "lasso_final-recipe"))

fit_parsnip &lt;- final_lasso |&gt;
  fit(v5_dat_train) |&gt;
  extract_fit_parsnip()

vis &lt;- fit_parsnip |&gt;
