Code
cor_including_zeros &lt;- full_join(
  lasso_fit |&gt;
    extract_fit_parsnip() |&gt;
    vi() |&gt;
    select(importance_notuning = Importance, Variable),
  final_lasso |&gt;
    fit(v5_dat_train) |&gt;
    extract_fit_parsnip() |&gt;
    vi(lambda = lowest_rmse$penalty) |&gt;
    select(importance_tuning = Importance, Variable),
  by = "Variable"
) |&gt;
  summarize(cor = cor(importance_notuning, importance_tuning))

cor_not_including_zeros &lt;- full_join(
  lasso_fit |&gt;
    extract_fit_parsnip() |&gt;
    vi() |&gt;
    filter_out(Importance == 0) |&gt;
    select(importance_notuning = Importance, Variable),
  final_lasso |&gt;
    fit(v5_dat_train) |&gt;
    extract_fit_parsnip() |&gt;
    vi(lambda = lowest_rmse$penalty) |&gt;
    filter_out(Importance == 0) |&gt;
    select(importance_tuning = Importance, Variable) ,
  by = "Variable"
) |&gt;
  summarize(cor = cor(importance_notuning, importance_tuning, use = "complete"))


Looks like more items included for the tuned model. Relatively similar top items. Correlation between estimates including all the zeros is 0.8 and without all the zeros (dropping those items) is 0.86.



